var DATA = {"expensive": "RANS CFD (2 h)", "stype": "Gaussian process", "design": "LHS 200 points", "pts": "-1|-0.5|0|0.5|1"};
console.log("Expensive model: " + DATA.expensive);
console.log("Surrogate: " + DATA.stype + " | Design: " + DATA.design);
// true function (expensive): f(x) = sin(3x) + 0.3*x^2 ; surrogate: quadratic fit
function expensive(x) { return Math.sin(3 * x) + 0.3 * x * x; }
var pts = DATA.pts.split("|").map(function (s) { return parseFloat(s); });
// least-squares quadratic fit: solve normal equations for [a,b,c] in a + b x + c x^2
var S = [[0,0,0],[0,0,0],[0,0,0]], t = [0,0,0];
pts.forEach(function (x) {
  var y = expensive(x), v = [1, x, x * x];
  for (var i = 0; i < 3; i++) { t[i] += v[i] * y; for (var j = 0; j < 3; j++) S[i][j] += v[i] * v[j]; }
});
// Gaussian elimination on 3x3
for (var k = 0; k < 3; k++) {
  var piv = S[k][k];
  for (var i = k + 1; i < 3; i++) { var f = S[i][k] / piv;
    for (var j = k; j < 3; j++) S[i][j] -= f * S[k][j]; t[i] -= f * t[k]; }
}
var c = [0,0,0];
for (var i = 2; i >= 0; i--) { var s = t[i]; for (var j = i + 1; j < 3; j++) s -= S[i][j] * c[j]; c[i] = s / S[i][i]; }
function surr(x) { return c[0] + c[1] * x + c[2] * x * x; }
var err = 0;
[-1, -0.5, 0, 0.5, 1].forEach(function (x) { err = Math.max(err, Math.abs(expensive(x) - surr(x))); });
console.log("Fitted quadratic: " + c.map(function (x) { return x.toFixed(4); }).join(", "));
console.log("Max error on test points: " + err.toFixed(4));
console.log("RESULT: surrogate trained on " + pts.length + " points; max error " + err.toFixed(4) + ".");

